const here = path.dirname(fileURLToPath(import.meta.url));
const J = JSON.stringify;
const ago = (days, h = 12) => { const d = new Date(Date.now() - days * 864e5); d.setUTCHours(h, Math.floor(Math.random() * 59)); return d.toISOString().replace('T', ' ').slice(0, 19); };

async function wavTone(seconds = 1.2, freq = 330) {
  const rate = 8000; const n = Math.floor(rate * seconds); const buf = Buffer.alloc(44 + n * 2);
  buf.write('RIFF', 0); buf.writeUInt32LE(36 + n * 2, 4); buf.write('WAVEfmt ', 8); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(1, 22);
  buf.writeUInt32LE(rate, 24); buf.writeUInt32LE(rate * 2, 28); buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34); buf.write('data', 36); buf.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) buf.writeInt16LE(Math.round(Math.sin((2 * Math.PI * freq * i) / rate) * 6000 * Math.min(1, (n - i) / 800)), 44 + i * 2);
  return storeFile('private', { buffer: buf, originalname: 'recording.wav', mimetype: 'audio/wav', size: buf.length }, null);
}

