    const g1 = await insert('groups', { name: 'Құран оқу · Кешкі топ', description: 'Дүйсенбі, сәрсенбі 19:00 — онлайн', teacher_id: adilet, curator_id: curator });
    const g2 = await insert('groups', { name: 'Әйелдер тобы', description: 'Сейсенбі, бейсенбі 11:00', teacher_id: aigerim, curator_id: curator });
